-- Phase 4 vertical slice: world-10 ("Linux I: Survival: First Shell") mission
-- content, generated from docs/12-world-story-bible.md. First world to use
-- the terminal_simulation ChallengeType (apps/web/src/lib/terminal/,
-- apps/web/src/components/guardians/challenges/TerminalChallenge.tsx) --
-- a real, client-side simulated Linux shell (virtual filesystem + command
-- interpreter), not a real VM/container. Mission 1 is cross-world-gated on
-- the previous world's boss mission, same convention as world_9_content.sql.

insert into public.campaigns (id, world_id, slug, title, description, sort_order) values
  ('campaign-10a', 'world-10', 'first-shell', '10A - First Shell', 'The recovered SkyPort maintenance controller runs Linux -- no interface, just a shell. Find what came home with it.', 1);

insert into public.operations (id, campaign_id, slug, title, description, sort_order) values
  ('operation-10a-1', 'campaign-10a', 'foundations', 'Foundations', 'Navigation and file discovery, learned as field tools before touching anything.', 1),
  ('operation-10a-2', 'campaign-10a', 'investigation', 'Investigation', 'Manual pages, filters, and locating the implant without disturbing the evidence.', 2);

insert into public.missions (
  id, world_id, campaign_id, operation_id, slug, title, description, difficulty,
  character_ids, prerequisites, required_skills, lab, rewards, is_boss, sort_order
) values
  ('mission-w10-01', 'world-10', 'campaign-10a', 'operation-10a-1', 'no-gui', 'No Graphical Interface', 'The recovered maintenance controller runs Linux. No monitor, no desktop -- just a shell and whatever came home with it.', 'intro', ARRAY['ava', 'byte'], '{"requiredMissionIds":["mission-w9-06"]}'::jsonb, null, '{"type":"none"}'::jsonb, '{"xp":60,"credits":10}'::jsonb, false, 1),
  ('mission-w10-02', 'world-10', 'campaign-10a', 'operation-10a-1', 'find-your-way', 'Find Your Way', 'Prove you can move through a filesystem you''ve never seen before -- pwd, cd, ls, nothing more.', 'beginner', ARRAY['byte'], '{"requiredMissionIds":["mission-w10-01"]}'::jsonb, null, '{"type":"simulation","simulationId":"linux-navigation-sim"}'::jsonb, '{"xp":90,"credits":15}'::jsonb, false, 2),
  ('mission-w10-03', 'world-10', 'campaign-10a', 'operation-10a-1', 'whats-actually-here', 'What''s Actually Here', 'This box has more files than you''ll ever read one at a time. Search for names instead of scrolling.', 'beginner', ARRAY['byte'], '{"requiredMissionIds":["mission-w10-02"]}'::jsonb, null, '{"type":"simulation","simulationId":"linux-find-sim"}'::jsonb, '{"xp":100,"credits":15}'::jsonb, false, 3),
  ('mission-w10-04', 'world-10', 'campaign-10a', 'operation-10a-2', 'ask-the-manual', 'Ask the Manual', 'Byte won''t explain a command before you''ve asked it yourself. The manual pages are always there.', 'beginner', ARRAY['byte'], '{"requiredMissionIds":["mission-w10-03"]}'::jsonb, null, '{"type":"simulation","simulationId":"linux-man-sim"}'::jsonb, '{"xp":100,"credits":15}'::jsonb, false, 4),
  ('mission-w10-05', 'world-10', 'campaign-10a', 'operation-10a-2', 'needle-in-the-log', 'Needle in the Log', 'Auth logs are noisy by design. The trick is filtering, not reading every line.', 'beginner', ARRAY['ava'], '{"requiredMissionIds":["mission-w10-04"]}'::jsonb, null, '{"type":"simulation","simulationId":"linux-grep-sim"}'::jsonb, '{"xp":90,"credits":15}'::jsonb, false, 5),
  ('mission-w10-06', 'world-10', 'campaign-10a', 'operation-10a-2', 'first-shell-boss', 'First Shell', 'Whatever came home from that rogue access point is on this box somewhere. Find its configuration, and don''t delete anything on the way.', 'boss', ARRAY['ava', 'byte'], '{"requiredMissionIds":["mission-w10-05"]}'::jsonb, null, '{"type":"simulation","simulationId":"first-shell-boss-sim"}'::jsonb, '{"xp":300,"credits":60,"badgeIds":["first-shell"],"skillXp":{"linux":50}}'::jsonb, true, 6);

insert into public.dialogue_lines (mission_id, sort_order, character_id, text) values
  ('mission-w10-01', 1, 'ava', 'The maintenance controller we pulled from SkyPort inventory just came back online under isolation. No monitor, no desktop -- just a shell.'),
  ('mission-w10-01', 2, 'ava', 'That''s normal for a machine like this, and it''s normal for us. Field work rarely looks like a movie.'),
  ('mission-w10-01', 3, 'byte', 'I can read what''s in front of us. I won''t narrate every keystroke, though -- you''ll actually remember a command you had to reach for yourself.'),
  ('mission-w10-01', 4, 'ava', 'Somewhere on this box is whatever came home from that rogue access point. Let''s go find it.'),
  ('mission-w10-02', 1, 'byte', 'Everything here is a path. Don''t know where you are? pwd. Don''t know what''s around you? ls. Moving is cd. That''s the whole toolkit for now.'),
  ('mission-w10-03', 1, 'byte', 'This box has more files than you''ll ever read one at a time. find looks for names so you don''t have to.'),
  ('mission-w10-04', 1, 'byte', 'I''m not going to tell you what a command does before you''ve asked it yourself. Try man first.'),
  ('mission-w10-05', 1, 'ava', 'Auth logs are noisy by design -- most of what''s in there is completely routine. The trick is filtering, not reading.'),
  ('mission-w10-06', 1, 'ava', 'Whatever came home from that access point is on this box somewhere. Find its configuration -- and don''t delete anything on the way. We need this intact for the record.'),
  ('mission-w10-06', 2, 'byte', 'Implant ID confirmed. And the config file references a service account: sentinel-sync.'),
  ('mission-w10-06', 3, 'ava', 'A service account with implant-level access. That''s not something a rogue AP sets up by itself -- someone gave it a job.'),
  ('mission-w10-06', 4, 'ava', 'Finding out what sentinel-sync can actually do means going deeper than survival commands. Time to learn this system as an administrator, not a tourist.');

insert into public.objectives (id, mission_id, sort_order, title, description) values
  ('mission-w10-01-o1', 'mission-w10-01', 1, 'Acknowledge the briefing', 'Confirm you''re ready to work without a graphical interface.'),
  ('mission-w10-02-o1', 'mission-w10-02', 1, 'Navigate to the closed ticket', 'Find the closed ticket with no requester on file and read its contents.'),
  ('mission-w10-03-o1', 'mission-w10-03', 1, 'Find the mismatched file', 'Locate the one file that breaks the tools directory''s naming convention.'),
  ('mission-w10-04-o1', 'mission-w10-04', 1, 'Read the end of the agent log', 'Use the manual, then read the end of the log instead of scrolling through it.'),
  ('mission-w10-05-o1', 'mission-w10-05', 1, 'Filter the failed logins', 'Isolate the failed login attempts and extract the flagged one.'),
  ('mission-w10-06-o1', 'mission-w10-06', 1, 'Locate the implant configuration', 'Find the implant''s configuration file and capture its identifier without disturbing it.');

insert into public.challenges (id, objective_id, sort_order, type, prompt, content, completion_conditions) values
  ('mission-w10-01-o1-c1', 'mission-w10-01-o1', 1, 'story_dialogue', 'Confirm you''re ready to continue.', '{"lines":[{"characterId":"ava","text":"No interface to lean on this time -- just the shell. Ready?"}]}'::jsonb, '{"acknowledged":true}'::jsonb),

  ('mission-w10-02-o1-c1', 'mission-w10-02-o1', 1, 'terminal_simulation', 'Find the closed ticket with no requester on file, and submit the code inside it.', '{"instructions":"Byte wants proof you can move through a filesystem you''ve never seen before. Somewhere under /var/skyport/ops/queue/2024-tickets/closed/ is a ticket that never should have been closed -- it has no requester on file. Read it and submit the code inside.","hostname":"skyport-mnt07","user":"recruit","filesystem":{"/etc/hostname":{"type":"file","content":"skyport-mnt07\n"},"/etc/skyport/mnt-controller.conf":{"type":"file","content":"# SkyPort Maintenance Controller\nrole=mnt-controller\nsite=skyport-3\nmanaged_by=facilities-ops\n"},"/opt/skyport/README.txt":{"type":"file","content":"This controller runs unattended. Facilities checks in over SSH during scheduled maintenance windows only.\n"},"/root":{"type":"dir","mode":"700","owner":"root"},"/home/recruit":{"type":"dir"},"/var/skyport/ops/queue/2024-tickets/open/README.txt":{"type":"file","content":"Open tickets awaiting facilities review.\n"},"/var/skyport/ops/queue/2024-tickets/closed/ticket-0091.txt":{"type":"file","content":"Ticket 0091: HVAC sensor recalibration. Closed by facilities-ops.\n"},"/var/skyport/ops/queue/2024-tickets/closed/ticket-0092.txt":{"type":"file","content":"Ticket 0092: Badge reader firmware update. Closed by facilities-ops.\n"},"/var/skyport/ops/queue/2024-tickets/closed/ticket-0093.txt":{"type":"file","content":"Ticket 0093 -- unscheduled, no requester on file.\nWAYPOINT-ALPHA-7719\n"},"/var/skyport/ops/archive/README.txt":{"type":"file","content":"Archived tickets older than one year.\n"}}}'::jsonb, '{"requiredFlag":"WAYPOINT-ALPHA-7719"}'::jsonb),

  ('mission-w10-03-o1-c1', 'mission-w10-03-o1', 1, 'terminal_simulation', 'Find the one file under /opt/skyport/tools/ that breaks the naming convention, and submit the code inside it.', '{"instructions":"Every module under /opt/skyport/tools/ follows the same naming convention -- one file doesn''t. Use find, not your eyes, to locate it.","hostname":"skyport-mnt07","user":"recruit","filesystem":{"/etc/hostname":{"type":"file","content":"skyport-mnt07\n"},"/etc/skyport/mnt-controller.conf":{"type":"file","content":"# SkyPort Maintenance Controller\nrole=mnt-controller\nsite=skyport-3\nmanaged_by=facilities-ops\n"},"/opt/skyport/README.txt":{"type":"file","content":"This controller runs unattended. Facilities checks in over SSH during scheduled maintenance windows only.\n"},"/root":{"type":"dir","mode":"700","owner":"root"},"/home/recruit":{"type":"dir"},"/opt/skyport/tools/diagnostics/notes.txt":{"type":"file","content":"Diagnostics module nominal.\n"},"/opt/skyport/tools/network/notes.txt":{"type":"file","content":"Network module nominal.\n"},"/opt/skyport/tools/power/notes.txt":{"type":"file","content":"Power module nominal.\n"},"/opt/skyport/tools/sensors/notes.txt":{"type":"file","content":"Sensor module nominal.\n"},"/opt/skyport/tools/logging/notes.txt":{"type":"file","content":"Logging module nominal.\n"},"/opt/skyport/tools/legacy/waypoint_beta.cfg":{"type":"file","content":"# legacy module, scheduled for removal\nWAYPOINT-BETA-4402\n"}}}'::jsonb, '{"requiredFlag":"WAYPOINT-BETA-4402"}'::jsonb),

  ('mission-w10-04-o1-c1', 'mission-w10-04-o1', 1, 'terminal_simulation', 'Read the end of the agent log without scrolling through the whole thing, and submit the code you find.', '{"instructions":"I''m not walking you through this one -- check the manual for a command that reads the end of a file first. Then point it at the agent log instead of scrolling past a night''s worth of routine heartbeats.","hostname":"skyport-mnt07","user":"recruit","filesystem":{"/etc/hostname":{"type":"file","content":"skyport-mnt07\n"},"/etc/skyport/mnt-controller.conf":{"type":"file","content":"# SkyPort Maintenance Controller\nrole=mnt-controller\nsite=skyport-3\nmanaged_by=facilities-ops\n"},"/opt/skyport/README.txt":{"type":"file","content":"This controller runs unattended. Facilities checks in over SSH during scheduled maintenance windows only.\n"},"/root":{"type":"dir","mode":"700","owner":"root"},"/home/recruit":{"type":"dir"},"/var/log/skyport/agent.log":{"type":"file","content":"2024-11-02 03:00:01 agent: heartbeat ok\n2024-11-02 04:00:01 agent: heartbeat ok\n2024-11-02 05:00:01 agent: heartbeat ok\n2024-11-02 06:00:01 agent: heartbeat ok\n2024-11-02 07:00:01 agent: heartbeat ok\n2024-11-02 08:00:01 agent: heartbeat ok\n2024-11-02 09:00:01 agent: heartbeat ok\n2024-11-02 09:00:02 agent: WAYPOINT-GAMMA-1188\n"}}}'::jsonb, '{"requiredFlag":"WAYPOINT-GAMMA-1188"}'::jsonb),

  ('mission-w10-05-o1-c1', 'mission-w10-05-o1', 1, 'terminal_simulation', 'Filter the auth log for failed logins and extract the code from the flagged attempt.', '{"instructions":"This log is mostly routine facilities-ops sessions. Filter for the failed attempts, and pull the code out of the last one.","hostname":"skyport-mnt07","user":"recruit","filesystem":{"/etc/hostname":{"type":"file","content":"skyport-mnt07\n"},"/etc/skyport/mnt-controller.conf":{"type":"file","content":"# SkyPort Maintenance Controller\nrole=mnt-controller\nsite=skyport-3\nmanaged_by=facilities-ops\n"},"/opt/skyport/README.txt":{"type":"file","content":"This controller runs unattended. Facilities checks in over SSH during scheduled maintenance windows only.\n"},"/root":{"type":"dir","mode":"700","owner":"root"},"/home/recruit":{"type":"dir"},"/var/log/skyport/auth.log":{"type":"file","content":"2024-11-02 01:00:03 sshd: session opened for user facilities-ops\n2024-11-02 01:04:11 sshd: session closed for user facilities-ops\n2024-11-02 06:00:05 sshd: session opened for user facilities-ops\n2024-11-02 06:12:47 sshd: session closed for user facilities-ops\n2024-11-02 09:41:02 sshd: Failed password for invalid user svc-tmp from 10.44.6.19\n2024-11-02 09:41:19 sshd: Failed password for invalid user svc-tmp from 10.44.6.19\n2024-11-02 09:41:33 sshd: Failed password for invalid user svc-tmp from 10.44.6.19\n2024-11-02 12:00:02 sshd: session opened for user facilities-ops\n2024-11-02 12:08:55 sshd: session closed for user facilities-ops\n2024-11-02 09:41:51 sshd: Failed password for invalid user svc-tmp from 10.44.6.19 code=WAYPOINT-DELTA-2635\n"}}}'::jsonb, '{"requiredFlag":"WAYPOINT-DELTA-2635"}'::jsonb),

  ('mission-w10-06-o1-c1', 'mission-w10-06-o1', 1, 'terminal_simulation', 'Locate the implant''s configuration file and submit its implant_id -- without deleting or altering anything.', '{"instructions":"Whatever came home from that rogue access point is somewhere on this box. Find its configuration file, and capture its implant_id -- without deleting or altering anything along the way. We need this intact for the record.","hostname":"skyport-mnt07","user":"recruit","filesystem":{"/etc/hostname":{"type":"file","content":"skyport-mnt07\n"},"/etc/skyport/mnt-controller.conf":{"type":"file","content":"# SkyPort Maintenance Controller\nrole=mnt-controller\nsite=skyport-3\nmanaged_by=facilities-ops\n"},"/etc/skyport/network.conf":{"type":"file","content":"# network config\ninterface=eth0\ndhcp=false\naddress=10.44.6.7/24\n"},"/etc/skyport/backup.conf":{"type":"file","content":"# backup schedule\nfrequency=weekly\nretention=30d\n"},"/etc/skyport/scripts/rotate-logs.sh":{"type":"file","content":"#!/bin/sh\n# rotates /var/log/skyport nightly\n"},"/etc/skyport/.implant/config.yml":{"type":"file","content":"# unauthorized -- not part of the facilities-ops baseline image\nimplant_id: SX-7F3A19\nservice_account: sentinel-sync\nc2_interval: 300\n","mode":"644","owner":"root"},"/opt/skyport/README.txt":{"type":"file","content":"This controller runs unattended. Facilities checks in over SSH during scheduled maintenance windows only.\n"},"/root":{"type":"dir","mode":"700","owner":"root"},"/home/recruit":{"type":"dir"}},"protectedPaths":["/etc/skyport/.implant","/etc/skyport/.implant/config.yml"]}'::jsonb, '{"requiredFlag":"SX-7F3A19","requireEvidencePreserved":true}'::jsonb);

insert into public.hints (challenge_id, tier, text, xp_cost, sort_order) values
  ('mission-w10-01-o1-c1', 'orientation', 'There''s nothing to solve here -- just confirm you''re ready to continue.', 0, 1),

  ('mission-w10-02-o1-c1', 'orientation', 'pwd tells you where you are. ls tells you what''s around you. cd moves you.', 10, 1),
  ('mission-w10-02-o1-c1', 'concept', 'Paths chain together with /. You can cd straight into a deep path, or move one directory at a time.', 20, 2),
  ('mission-w10-02-o1-c1', 'solution', 'cd /var/skyport/ops/queue/2024-tickets/closed then ls to see the tickets, then cat ticket-0093.txt -- it''s the one with no requester on file. Submit WAYPOINT-ALPHA-7719.', 30, 3),

  ('mission-w10-03-o1-c1', 'orientation', 'ls -R would work, but you''re looking for one filename among dozens -- there''s a faster tool for that.', 15, 1),
  ('mission-w10-03-o1-c1', 'concept', 'find searches by name across an entire directory tree in one command, starting from wherever you point it.', 25, 2),
  ('mission-w10-03-o1-c1', 'tool_direction', 'Try find /opt/skyport/tools -name "*.cfg" -- every other module uses notes.txt.', 35, 3),
  ('mission-w10-03-o1-c1', 'solution', 'find /opt/skyport/tools -name "*.cfg" turns up /opt/skyport/tools/legacy/waypoint_beta.cfg. cat it and submit WAYPOINT-BETA-4402.', 45, 4),

  ('mission-w10-04-o1-c1', 'orientation', 'man <command> shows you what a command does before you run it.', 10, 1),
  ('mission-w10-04-o1-c1', 'concept', 'The command you want reads lines from the end of a file, not the beginning -- man tail will confirm it.', 20, 2),
  ('mission-w10-04-o1-c1', 'solution', 'man tail, then tail -n 2 /var/log/skyport/agent.log. The last line is the one that matters. Submit WAYPOINT-GAMMA-1188.', 30, 3),

  ('mission-w10-05-o1-c1', 'orientation', 'You don''t need to read every line -- most of this log is routine session opens and closes.', 15, 1),
  ('mission-w10-05-o1-c1', 'concept', 'grep pulls out only the lines matching a pattern. "Failed password" is the pattern you want.', 25, 2),
  ('mission-w10-05-o1-c1', 'tool_direction', 'Try grep "Failed password" /var/log/skyport/auth.log, then look at the last matching line specifically.', 35, 3),
  ('mission-w10-05-o1-c1', 'solution', 'grep "Failed password" /var/log/skyport/auth.log shows four failed attempts from svc-tmp -- the last one carries code=WAYPOINT-DELTA-2635. Submit WAYPOINT-DELTA-2635.', 45, 4),

  ('mission-w10-06-o1-c1', 'orientation', 'Plain ls won''t show everything in /etc/skyport -- some things don''t want to be seen.', 20, 1),
  ('mission-w10-06-o1-c1', 'concept', 'Files and directories starting with a dot are hidden from a normal listing, not from you.', 30, 2),
  ('mission-w10-06-o1-c1', 'tool_direction', 'Try ls -a /etc/skyport, or find /etc/skyport -name ".implant" directly.', 40, 3),
  ('mission-w10-06-o1-c1', 'near_solution', 'cat /etc/skyport/.implant/config.yml once you''ve found it -- read it, don''t touch it.', 50, 4),
  ('mission-w10-06-o1-c1', 'solution', '/etc/skyport/.implant/config.yml is hidden from plain ls -- find it with -a or find, then cat (never rm) it. implant_id: SX-7F3A19. Submit SX-7F3A19.', 65, 5);
